import type { HighSchoolLevel } from "../lib/high-school-store";

export type HighSchoolTopicBand = "foundation" | "development" | "extension" | "all_levels";
export type HighSchoolTopicMode = "evidence" | "reasoning" | "decision" | "reflection";

export type HighSchoolTopicUnit = {
  id: string;
  packId: string;
  topicId: string;
  title: string;
  band: HighSchoolTopicBand;
  mode: HighSchoolTopicMode;
  cue: string;
  prompt: string;
  options?: readonly string[];
  bestOption?: string;
  explanation: string;
  reflectionPrompt?: string;
  boundaryNote?: string;
};

/**
 * Original Rounds topic units are intentionally separate from the reviewed
 * starter activities. The catalogue is extended per subject without copying
 * external curriculum wording or claiming examination alignment.
 */
function topicUnit(
  id: string,
  packId: string,
  topicId: string,
  title: string,
  band: Exclude<HighSchoolTopicBand, "all_levels">,
  mode: Exclude<HighSchoolTopicMode, "reflection">,
  cue: string,
  prompt: string,
  options: readonly string[],
  bestOption: string,
  explanation: string,
  boundaryNote?: string,
): HighSchoolTopicUnit {
  return { id, packId, topicId, title, band, mode, cue, prompt, options, bestOption, explanation, boundaryNote };
}

function reflectionCompanion(unit: HighSchoolTopicUnit): HighSchoolTopicUnit {
  return {
    id: `${unit.id}-reflection`,
    packId: unit.packId,
    topicId: `${unit.topicId}-reflection`,
    title: `Reflect on ${unit.title.toLowerCase()}`,
    band: unit.band,
    mode: "reflection",
    cue: "PRIVATE REFLECTION",
    prompt: "Pause and write one short private note about the study move you would use next time.",
    explanation: "Private reflection helps you notice a useful study move without asking Rounds to judge a personal response.",
    reflectionPrompt: `What is one question, check, or strategy you would carry forward from “${unit.title}”?`,
    boundaryNote: unit.boundaryNote,
  };
}

