function pathwayUnit(
  id: string,
  packId: string,
  topicId: string,
  title: string,
  band: Exclude<HighSchoolTopicBand, "all_levels">,
  mode: Exclude<HighSchoolTopicMode, "reflection">,
  cue: string,
  prompt: string,
  bestOption: string,
  explanation: string,
  boundaryNote?: string,
): HighSchoolTopicUnit {
  return topicUnit(id, packId, topicId, title, band, mode, cue, prompt, [bestOption, "Make a broader conclusion than the stated information allows.", "Ignore the stated record or detail.", "Replace the evidence with an unsupported personal claim."], bestOption, explanation, boundaryNote);
}

