export const HIGH_SCHOOL_TOPIC_UNITS: readonly HighSchoolTopicUnit[] = [...CORE_TOPIC_UNITS, ...PATHWAY_TWO_UNITS, ...PATHWAY_THREE_UNITS].flatMap((unit) => [unit, reflectionCompanion(unit)]);

export function topicUnitsForPack(packId: string): HighSchoolTopicUnit[] {
  return HIGH_SCHOOL_TOPIC_UNITS.filter((unit) => unit.packId === packId);
}

export function topicUnitForId(unitId: string): HighSchoolTopicUnit | null {
  return HIGH_SCHOOL_TOPIC_UNITS.find((unit) => unit.id === unitId) ?? null;
}

export function learningBandForLevel(level: HighSchoolLevel): Exclude<HighSchoolTopicBand, "all_levels"> {
  if (level === "s1" || level === "s2") return "foundation";
  if (level === "s3" || level === "s4") return "development";
  return "extension";
}

export function isUnitRecommendedForLevel(unit: HighSchoolTopicUnit, level: HighSchoolLevel): boolean {
  return unit.band === "all_levels" || unit.band === learningBandForLevel(level);
}

export function topicUnitModesLabel(mode: HighSchoolTopicMode): string {
  return ({ evidence: "Read evidence", reasoning: "Reason it through", decision: "Choose a next step", reflection: "Reflect privately" })[mode];
}
